-- Speak sessions: 10 of them, N5.
--
-- Generated by `pnpm -C nihongo/backend seed:speak` from
-- backend/src/pipeline/data/speak. Do not edit: change the data and generate a
-- new seed. Audio was confirmed in the bucket when this was written.
--
-- Every session arrives UNPUBLISHED with a pending row in the admin review
-- queue. Approving it there is the only thing that publishes it.
--
-- Then every prompt in the database — these sessions and all earlier ones — as
-- a study item, so a prompt answered "Not quite" can come back in reviews.
--
-- Idempotent: nothing here overwrites an existing session, its steps, a study
-- item, or a review decision already made.

-- N5 · 11 · I am eating
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-11-te-imasu', 'lang-ja', ll.id, 'n5-11-te-imasu', 11, '食べています', 'I am eating', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-11-te-imasu-s0', 'spk-ja-n5-11-te-imasu', 0, 'explain', 'You know the {て} form from {たべてください}. Put {います} after it and you say what is happening right now. {たべています}. "I am eating."', NULL, NULL, NULL),
  ('spk-ja-n5-11-te-imasu-s1', 'spk-ja-n5-11-te-imasu', 1, 'prompt', 'How would you say "I am eating"?', '食べています。', 'たべて います。', NULL),
  ('spk-ja-n5-11-te-imasu-s2', 'spk-ja-n5-11-te-imasu', 2, 'prompt', 'How would you say "I am eating sushi"?', 'すしを食べています。', 'すし お たべて います。', NULL),
  ('spk-ja-n5-11-te-imasu-s3', 'spk-ja-n5-11-te-imasu', 3, 'prompt', 'How would you say "I am watching TV"?', 'テレビを見ています。', 'テレビ お みて います。', NULL),
  ('spk-ja-n5-11-te-imasu-s4', 'spk-ja-n5-11-te-imasu', 4, 'explain', '{よみます} gives {よんで}, so it is {よんでいます}. Same as in {よんでください}.', NULL, NULL, NULL),
  ('spk-ja-n5-11-te-imasu-s5', 'spk-ja-n5-11-te-imasu', 5, 'prompt', 'How would you say "I am reading a book"?', '本を読んでいます。', 'ほん お よんで います。', NULL),
  ('spk-ja-n5-11-te-imasu-s6', 'spk-ja-n5-11-te-imasu', 6, 'prompt', 'How would you say "I am drinking tea"?', 'おちゃを飲んでいます。', 'おちゃ お のんで います。', NULL),
  ('spk-ja-n5-11-te-imasu-s7', 'spk-ja-n5-11-te-imasu', 7, 'prompt', 'How would you say "Are you drinking tea?"', 'おちゃを飲んでいますか。', 'おちゃ お のんで います か。', NULL),
  ('spk-ja-n5-11-te-imasu-s8', 'spk-ja-n5-11-te-imasu', 8, 'prompt', 'How would you say "Are you reading a book now?"', '今、本を読んでいますか。', 'いま、ほん お よんで います か。', NULL),
  ('spk-ja-n5-11-te-imasu-s9', 'spk-ja-n5-11-te-imasu', 9, 'prompt', 'How would you say "Yes, I am reading a book now"?', 'はい、今、本を読んでいます。', 'はい、いま、ほん お よんで います。', NULL),
  ('spk-ja-n5-11-te-imasu-s10', 'spk-ja-n5-11-te-imasu', 10, 'explain', 'For "am not", change {います} to {いません}. {たべていません}.', NULL, NULL, NULL),
  ('spk-ja-n5-11-te-imasu-s11', 'spk-ja-n5-11-te-imasu', 11, 'prompt', 'How would you say "No, I am not eating"?', 'いいえ、食べていません。', 'いいえ、たべて いません。', NULL),
  ('spk-ja-n5-11-te-imasu-s12', 'spk-ja-n5-11-te-imasu', 12, 'prompt', 'How would you say "I am not watching TV now"?', '今、テレビを見ていません。', 'いま、テレビ お みて いません。', NULL),
  ('spk-ja-n5-11-te-imasu-s13', 'spk-ja-n5-11-te-imasu', 13, 'explain', '"Write" is {かきます}, and you know {かいて}. So {かいています}.', NULL, NULL, NULL),
  ('spk-ja-n5-11-te-imasu-s14', 'spk-ja-n5-11-te-imasu', 14, 'prompt', 'How would you say "I am writing my name"?', '名前を書いています。', 'なまえ お かいて います。', NULL),
  ('spk-ja-n5-11-te-imasu-s15', 'spk-ja-n5-11-te-imasu', 15, 'prompt', 'How would you say "I am listening to the teacher''s talk now"?', '今、先生の話を聞いています。', 'いま、せんせい の はなし お きいて います。', NULL),
  ('spk-ja-n5-11-te-imasu-s16', 'spk-ja-n5-11-te-imasu', 16, 'explain', 'This form also says where someone lives. Living somewhere is a state that goes on, so Japanese uses it here too. "Live" is {すみます}, and it becomes {すんで}. {すんでいます}.', NULL, NULL, NULL),
  ('spk-ja-n5-11-te-imasu-s17', 'spk-ja-n5-11-te-imasu', 17, 'prompt', 'How would you say "I live in Japan"?', '日本に住んでいます。', 'にほん に すんで います。', NULL),
  ('spk-ja-n5-11-te-imasu-s18', 'spk-ja-n5-11-te-imasu', 18, 'prompt', 'How would you say "Do you live in Japan?"', '日本に住んでいますか。', 'にほん に すんで います か。', NULL),
  ('spk-ja-n5-11-te-imasu-s19', 'spk-ja-n5-11-te-imasu', 19, 'explain', '"Where" is {どこ}. It sits where the answer would sit.', NULL, NULL, NULL),
  ('spk-ja-n5-11-te-imasu-s20', 'spk-ja-n5-11-te-imasu', 20, 'prompt', 'How would you say "Where do you live?"', 'どこに住んでいますか。', 'どこ に すんで います か。', NULL),
  ('spk-ja-n5-11-te-imasu-s21', 'spk-ja-n5-11-te-imasu', 21, 'prompt', 'How would you say "The teacher lives in Japan"?', '先生は日本に住んでいます。', 'せんせい わ にほん に すんで います。', NULL),
  ('spk-ja-n5-11-te-imasu-s22', 'spk-ja-n5-11-te-imasu', 22, 'prompt', 'How would you say "Now I am watching TV at home"?', '今、うちでテレビを見ています。', 'いま、うち で テレビ お みて います。', NULL),
  ('spk-ja-n5-11-te-imasu-s23', 'spk-ja-n5-11-te-imasu', 23, 'prompt', 'How would you say "I am reading a book at school now"?', '今、学校で本を読んでいます。', 'いま、がっこう で ほん お よんで います。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-11-te-imasu')
ON CONFLICT (session_id, index) DO NOTHING;

