-- N5 · 12 · There is, I have
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-12-arimasu', 'lang-ja', ll.id, 'n5-12-arimasu', 12, '本があります', 'There is, I have', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-12-arimasu-s0', 'spk-ja-n5-12-arimasu', 0, 'explain', 'Now saying that something exists. For things, the word is {あります}. The thing that exists takes {が}. {みずがあります}, "there is water."', NULL, NULL, NULL),
  ('spk-ja-n5-12-arimasu-s1', 'spk-ja-n5-12-arimasu', 1, 'prompt', 'How would you say "There is water"?', '水があります。', 'みず が あります。', NULL),
  ('spk-ja-n5-12-arimasu-s2', 'spk-ja-n5-12-arimasu', 2, 'prompt', 'How would you say "There is a book"?', '本があります。', 'ほん が あります。', NULL),
  ('spk-ja-n5-12-arimasu-s3', 'spk-ja-n5-12-arimasu', 3, 'prompt', 'How would you say "There is sushi"?', 'すしがあります。', 'すし が あります。', NULL),
  ('spk-ja-n5-12-arimasu-s4', 'spk-ja-n5-12-arimasu', 4, 'explain', '"Here" is {ここ}. The place where something is takes {に}.', NULL, NULL, NULL),
  ('spk-ja-n5-12-arimasu-s5', 'spk-ja-n5-12-arimasu', 5, 'prompt', 'How would you say "There is a book here"?', 'ここに本があります。', 'ここ に ほん が あります。', NULL),
  ('spk-ja-n5-12-arimasu-s6', 'spk-ja-n5-12-arimasu', 6, 'explain', 'A desk is {つくえ}. The top of something is {うえ}. So "on the desk" is "the desk''s top", {つくえのうえ}.', NULL, NULL, NULL),
  ('spk-ja-n5-12-arimasu-s7', 'spk-ja-n5-12-arimasu', 7, 'prompt', 'How would you say "There is a book on the desk"?', 'つくえの上に本があります。', 'つくえ の うえ に ほん が あります。', NULL),
  ('spk-ja-n5-12-arimasu-s8', 'spk-ja-n5-12-arimasu', 8, 'prompt', 'How would you say "There is tea on the desk"?', 'つくえの上におちゃがあります。', 'つくえ の うえ に おちゃ が あります。', NULL),
  ('spk-ja-n5-12-arimasu-s9', 'spk-ja-n5-12-arimasu', 9, 'prompt', 'How would you say "Is there a book on the desk?"', 'つくえの上に本がありますか。', 'つくえ の うえ に ほん が あります か。', NULL),
  ('spk-ja-n5-12-arimasu-s10', 'spk-ja-n5-12-arimasu', 10, 'explain', 'For "there isn''t", use {ありません}. In a "not" sentence the thing usually takes the topic word, the one you hear in {ほんは}. {ここにほんはありません}.', NULL, NULL, NULL),
  ('spk-ja-n5-12-arimasu-s11', 'spk-ja-n5-12-arimasu', 11, 'prompt', 'How would you say "There is no book here"?', 'ここに本はありません。', 'ここ に ほん わ ありません。', NULL),
  ('spk-ja-n5-12-arimasu-s12', 'spk-ja-n5-12-arimasu', 12, 'explain', 'For people and animals, you say {います} instead. A friend is {ともだち}.', NULL, NULL, NULL),
  ('spk-ja-n5-12-arimasu-s13', 'spk-ja-n5-12-arimasu', 13, 'prompt', 'How would you say "There is a friend here"?', 'ここに友だちがいます。', 'ここ に ともだち が います。', NULL),
  ('spk-ja-n5-12-arimasu-s14', 'spk-ja-n5-12-arimasu', 14, 'prompt', 'How would you say "There is a teacher at school"?', '学校に先生がいます。', 'がっこう に せんせい が います。', NULL),
  ('spk-ja-n5-12-arimasu-s15', 'spk-ja-n5-12-arimasu', 15, 'prompt', 'How would you say "Is there a teacher at school?"', '学校に先生がいますか。', 'がっこう に せんせい が います か。', NULL),
  ('spk-ja-n5-12-arimasu-s16', 'spk-ja-n5-12-arimasu', 16, 'prompt', 'How would you say "There is no teacher here"?', 'ここに先生はいません。', 'ここ に せんせい わ いません。', NULL),
  ('spk-ja-n5-12-arimasu-s17', 'spk-ja-n5-12-arimasu', 17, 'explain', 'A dog is {いぬ}.', NULL, NULL, NULL),
  ('spk-ja-n5-12-arimasu-s18', 'spk-ja-n5-12-arimasu', 18, 'prompt', 'How would you say "There is a dog at home"?', 'うちにいぬがいます。', 'うち に いぬ が います。', NULL),
  ('spk-ja-n5-12-arimasu-s19', 'spk-ja-n5-12-arimasu', 19, 'prompt', 'How would you say "Do you have a dog at home?"', 'うちにいぬがいますか。', 'うち に いぬ が います か。', NULL),
  ('spk-ja-n5-12-arimasu-s20', 'spk-ja-n5-12-arimasu', 20, 'explain', 'To say "I have a friend in Japan", Japanese says "in Japan there is a friend."', NULL, NULL, NULL),
  ('spk-ja-n5-12-arimasu-s21', 'spk-ja-n5-12-arimasu', 21, 'prompt', 'How would you say "I have a friend in Japan"?', '日本に友だちがいます。', 'にほん に ともだち が います。', NULL),
  ('spk-ja-n5-12-arimasu-s22', 'spk-ja-n5-12-arimasu', 22, 'prompt', 'How would you say "Do you have a friend in Japan?"', '日本に友だちがいますか。', 'にほん に ともだち が います か。', NULL),
  ('spk-ja-n5-12-arimasu-s23', 'spk-ja-n5-12-arimasu', 23, 'prompt', 'How would you say "Yes, I do"?', 'はい、います。', 'はい、います。', NULL),
  ('spk-ja-n5-12-arimasu-s24', 'spk-ja-n5-12-arimasu', 24, 'prompt', 'How would you say "No, I don''t"?', 'いいえ、いません。', 'いいえ、いません。', NULL),
  ('spk-ja-n5-12-arimasu-s25', 'spk-ja-n5-12-arimasu', 25, 'explain', 'Things work the same way. {ほんがあります} can also mean "I have a book".', NULL, NULL, NULL),
  ('spk-ja-n5-12-arimasu-s26', 'spk-ja-n5-12-arimasu', 26, 'prompt', 'How would you say "I have a book"?', '本があります。', 'ほん が あります。', NULL),
  ('spk-ja-n5-12-arimasu-s27', 'spk-ja-n5-12-arimasu', 27, 'prompt', 'How would you say "There is a quiet restaurant in Japan"?', '日本にしずかなレストランがあります。', 'にほん に しずかな レストラン が あります。', NULL),
  ('spk-ja-n5-12-arimasu-s28', 'spk-ja-n5-12-arimasu', 28, 'prompt', 'How would you say "There is a big school in Japan"?', '日本に大きい学校があります。', 'にほん に おおきい がっこう が あります。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-12-arimasu')
ON CONFLICT (session_id, index) DO NOTHING;

