-- N5 · 13 · May I?
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-13-temoii', 'lang-ja', ll.id, 'n5-13-temoii', 13, '見てもいいですか', 'May I?', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-13-temoii-s0', 'spk-ja-n5-13-temoii', 0, 'explain', 'To ask permission, take the {て} form and add {もいいですか}. It means "is it all right even if". {たべてもいいですか}, "may I eat?"', NULL, NULL, NULL),
  ('spk-ja-n5-13-temoii-s1', 'spk-ja-n5-13-temoii', 1, 'prompt', 'How would you say "May I eat?"', '食べてもいいですか。', 'たべても いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s2', 'spk-ja-n5-13-temoii', 2, 'prompt', 'How would you say "May I eat sushi?"', 'すしを食べてもいいですか。', 'すし お たべても いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s3', 'spk-ja-n5-13-temoii', 3, 'prompt', 'How would you say "May I look at this?"', 'これを見てもいいですか。', 'これ お みても いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s4', 'spk-ja-n5-13-temoii', 4, 'prompt', 'How would you say "May I drink tea?"', 'おちゃを飲んでもいいですか。', 'おちゃ お のんでも いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s5', 'spk-ja-n5-13-temoii', 5, 'explain', '"This", before a noun, is {この}. {このほん}, this book.', NULL, NULL, NULL),
  ('spk-ja-n5-13-temoii-s6', 'spk-ja-n5-13-temoii', 6, 'prompt', 'How would you say "May I read this book?"', 'この本を読んでもいいですか。', 'この ほん お よんでも いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s7', 'spk-ja-n5-13-temoii', 7, 'explain', 'To answer, say {いいです}, "it is fine". Or say {だめです}, "no, that is not allowed".', NULL, NULL, NULL),
  ('spk-ja-n5-13-temoii-s8', 'spk-ja-n5-13-temoii', 8, 'prompt', 'How would you say "Yes, it is fine"?', 'はい、いいです。', 'はい、いい です。', NULL),
  ('spk-ja-n5-13-temoii-s9', 'spk-ja-n5-13-temoii', 9, 'prompt', 'How would you say "No, you may not"?', 'いいえ、だめです。', 'いいえ、だめ です。', 'Clear but blunt. Use it for rules, not to refuse a friend.'),
  ('spk-ja-n5-13-temoii-s10', 'spk-ja-n5-13-temoii', 10, 'prompt', 'How would you say "May I go home?"', 'うちに帰ってもいいですか。', 'うち に かえっても いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s11', 'spk-ja-n5-13-temoii', 11, 'prompt', 'How would you say "May I go to the restaurant?"', 'レストランに行ってもいいですか。', 'レストラン に いっても いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s12', 'spk-ja-n5-13-temoii', 12, 'prompt', 'How would you say "May I go to your home?"', 'あなたのうちに行ってもいいですか。', 'あなた の うち に いっても いい です か。', 'Japanese says go, not come, when you head to someone else''s place.'),
  ('spk-ja-n5-13-temoii-s13', 'spk-ja-n5-13-temoii', 13, 'prompt', 'How would you say "May I write here?"', 'ここに書いてもいいですか。', 'ここ に かいても いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s14', 'spk-ja-n5-13-temoii', 14, 'prompt', 'How would you say "May I write my name here?"', 'ここに名前を書いてもいいですか。', 'ここ に なまえ お かいても いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s15', 'spk-ja-n5-13-temoii', 15, 'explain', 'Remember {で}, for the place where you do something.', NULL, NULL, NULL),
  ('spk-ja-n5-13-temoii-s16', 'spk-ja-n5-13-temoii', 16, 'prompt', 'How would you say "May I watch TV here?"', 'ここでテレビを見てもいいですか。', 'ここ で テレビ お みても いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s17', 'spk-ja-n5-13-temoii', 17, 'prompt', 'How would you say "May I eat here?"', 'ここで食べてもいいですか。', 'ここ で たべても いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s18', 'spk-ja-n5-13-temoii', 18, 'prompt', 'How would you say "May I drink water here?"', 'ここで水を飲んでもいいですか。', 'ここ で みず お のんでも いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s19', 'spk-ja-n5-13-temoii', 19, 'prompt', 'How would you say "Yes, you may eat here"?', 'はい、ここで食べてもいいです。', 'はい、ここ で たべても いい です。', NULL),
  ('spk-ja-n5-13-temoii-s20', 'spk-ja-n5-13-temoii', 20, 'prompt', 'How would you say "May I go home now?"', '今、うちに帰ってもいいですか。', 'いま、うち に かえっても いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s21', 'spk-ja-n5-13-temoii', 21, 'prompt', 'How would you say "May I go home tomorrow?"', 'あした、うちに帰ってもいいですか。', 'あした、うち に かえっても いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s22', 'spk-ja-n5-13-temoii', 22, 'prompt', 'How would you say "There is tea here. May I drink it?"', 'ここにおちゃがあります。飲んでもいいですか。', 'ここ に おちゃ が あります。のんでも いい です か。', NULL),
  ('spk-ja-n5-13-temoii-s23', 'spk-ja-n5-13-temoii', 23, 'prompt', 'How would you say "May I read the teacher''s book?"', '先生の本を読んでもいいですか。', 'せんせい の ほん お よんでも いい です か。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-13-temoii')
ON CONFLICT (session_id, index) DO NOTHING;

