-- N5 · 14 · After doing, then
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-14-tekara', 'lang-ja', ll.id, 'n5-14-tekara', 14, '食べてから行きます', 'After doing, then', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-14-tekara-s0', 'spk-ja-n5-14-tekara', 0, 'explain', 'To say one thing happens after another, take the {て} form and add {から}. {たべてから}, "after I eat". You have heard {から} as "because". After a {て} form, it means "after".', NULL, NULL, NULL),
  ('spk-ja-n5-14-tekara-s1', 'spk-ja-n5-14-tekara', 1, 'prompt', 'How would you say "After I eat, I go"?', '食べてから、行きます。', 'たべて から、いきます。', NULL),
  ('spk-ja-n5-14-tekara-s2', 'spk-ja-n5-14-tekara', 2, 'prompt', 'How would you say "After I eat sushi, I go home"?', 'すしを食べてから、うちに帰ります。', 'すし お たべて から、うち に かえります。', NULL),
  ('spk-ja-n5-14-tekara-s3', 'spk-ja-n5-14-tekara', 3, 'prompt', 'How would you say "After I read a book, I watch TV"?', '本を読んでから、テレビを見ます。', 'ほん お よんで から、テレビ お みます。', NULL),
  ('spk-ja-n5-14-tekara-s4', 'spk-ja-n5-14-tekara', 4, 'prompt', 'How would you say "After I drink tea, I go to school"?', 'おちゃを飲んでから、学校に行きます。', 'おちゃ お のんで から、がっこう に いきます。', NULL),
  ('spk-ja-n5-14-tekara-s5', 'spk-ja-n5-14-tekara', 5, 'prompt', 'How would you say "After I watch TV, I read a book"?', 'テレビを見てから、本を読みます。', 'テレビ お みて から、ほん お よみます。', NULL),
  ('spk-ja-n5-14-tekara-s6', 'spk-ja-n5-14-tekara', 6, 'prompt', 'How would you say "After I go to school, I go home"?', '学校に行ってから、うちに帰ります。', 'がっこう に いって から、うち に かえります。', NULL),
  ('spk-ja-n5-14-tekara-s7', 'spk-ja-n5-14-tekara', 7, 'prompt', 'How would you say "After I eat, I want to watch TV"?', '食べてから、テレビを見たいです。', 'たべて から、テレビ お みたい です。', NULL),
  ('spk-ja-n5-14-tekara-s8', 'spk-ja-n5-14-tekara', 8, 'prompt', 'How would you say "After you eat, please come"?', '食べてから、来てください。', 'たべて から、きて ください。', NULL),
  ('spk-ja-n5-14-tekara-s9', 'spk-ja-n5-14-tekara', 9, 'prompt', 'How would you say "After we eat, let''s go home"?', '食べてから、うちに帰りましょう。', 'たべて から、うち に かえりましょう。', NULL),
  ('spk-ja-n5-14-tekara-s10', 'spk-ja-n5-14-tekara', 10, 'explain', 'To put it in the past, change only the last verb. {たべてから、いきました}.', NULL, NULL, NULL),
  ('spk-ja-n5-14-tekara-s11', 'spk-ja-n5-14-tekara', 11, 'prompt', 'How would you say "After I ate sushi, I went home"?', 'すしを食べてから、うちに帰りました。', 'すし お たべて から、うち に かえりました。', NULL),
  ('spk-ja-n5-14-tekara-s12', 'spk-ja-n5-14-tekara', 12, 'prompt', 'How would you say "Yesterday, after I read a book, I watched TV"?', 'きのう、本を読んでから、テレビを見ました。', 'きのう、ほん お よんで から、テレビ お みました。', NULL),
  ('spk-ja-n5-14-tekara-s13', 'spk-ja-n5-14-tekara', 13, 'prompt', 'How would you say "After I eat, may I watch TV?"', '食べてから、テレビを見てもいいですか。', 'たべて から、テレビ お みても いい です か。', NULL),
  ('spk-ja-n5-14-tekara-s14', 'spk-ja-n5-14-tekara', 14, 'prompt', 'How would you say "After you eat at the restaurant, please come to my home"?', 'レストランで食べてから、わたしのうちに来てください。', 'レストラン で たべて から、わたし の うち に きて ください。', NULL),
  ('spk-ja-n5-14-tekara-s15', 'spk-ja-n5-14-tekara', 15, 'explain', '"First" is {まず}. It starts the sentence.', NULL, NULL, NULL),
  ('spk-ja-n5-14-tekara-s16', 'spk-ja-n5-14-tekara', 16, 'prompt', 'How would you say "First I eat sushi, and then I go home"?', 'まず、すしを食べてから、うちに帰ります。', 'まず、すし お たべて から、うち に かえります。', NULL),
  ('spk-ja-n5-14-tekara-s17', 'spk-ja-n5-14-tekara', 17, 'prompt', 'How would you say "First I read a book, and then I watch TV"?', 'まず、本を読んでから、テレビを見ます。', 'まず、ほん お よんで から、テレビ お みます。', NULL),
  ('spk-ja-n5-14-tekara-s18', 'spk-ja-n5-14-tekara', 18, 'prompt', 'How would you say "Every day, after I go home, I read books"?', '毎日、うちに帰ってから、本を読みます。', 'まいにち、うち に かえって から、ほん お よみます。', NULL),
  ('spk-ja-n5-14-tekara-s19', 'spk-ja-n5-14-tekara', 19, 'prompt', 'How would you say "Every day, after I eat, I drink tea"?', '毎日、食べてから、おちゃを飲みます。', 'まいにち、たべて から、おちゃ お のみます。', NULL),
  ('spk-ja-n5-14-tekara-s20', 'spk-ja-n5-14-tekara', 20, 'prompt', 'How would you say "First write your name, and then please read this"?', 'まず、名前を書いてから、これを読んでください。', 'まず、なまえ お かいて から、これ お よんで ください。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-14-tekara')
ON CONFLICT (session_id, index) DO NOTHING;

