-- N5 · 15 · It was delicious
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-15-katta', 'lang-ja', ll.id, 'n5-15-katta', 15, 'おいしかったです', 'It was delicious', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-15-katta-s0', 'spk-ja-n5-15-katta', 0, 'explain', 'Describing words have a past too. For the {い} kind, drop the final {い} and add {かったです}. {おいしい} becomes {おいしかったです}. "It was delicious."', NULL, NULL, NULL),
  ('spk-ja-n5-15-katta-s1', 'spk-ja-n5-15-katta', 1, 'prompt', 'How would you say "The sushi was delicious"?', 'すしはおいしかったです。', 'すし わ おいしかった です。', NULL),
  ('spk-ja-n5-15-katta-s2', 'spk-ja-n5-15-katta', 2, 'prompt', 'How would you say "The tea was delicious"?', 'おちゃはおいしかったです。', 'おちゃ わ おいしかった です。', NULL),
  ('spk-ja-n5-15-katta-s3', 'spk-ja-n5-15-katta', 3, 'explain', 'For "was not", drop the {い} and add {くなかったです}. {おいしくなかったです}.', NULL, NULL, NULL),
  ('spk-ja-n5-15-katta-s4', 'spk-ja-n5-15-katta', 4, 'prompt', 'How would you say "The tea was not delicious"?', 'おちゃはおいしくなかったです。', 'おちゃ わ おいしくなかった です。', NULL),
  ('spk-ja-n5-15-katta-s5', 'spk-ja-n5-15-katta', 5, 'prompt', 'How would you say "Was the sushi delicious?"', 'すしはおいしかったですか。', 'すし わ おいしかった です か。', NULL),
  ('spk-ja-n5-15-katta-s6', 'spk-ja-n5-15-katta', 6, 'prompt', 'How would you say "Yes, it was delicious"?', 'はい、おいしかったです。', 'はい、おいしかった です。', NULL),
  ('spk-ja-n5-15-katta-s7', 'spk-ja-n5-15-katta', 7, 'prompt', 'How would you say "No, it was not delicious"?', 'いいえ、おいしくなかったです。', 'いいえ、おいしくなかった です。', NULL),
  ('spk-ja-n5-15-katta-s8', 'spk-ja-n5-15-katta', 8, 'prompt', 'How would you say "The restaurant was big"?', 'レストランは大きかったです。', 'レストラン わ おおきかった です。', NULL),
  ('spk-ja-n5-15-katta-s9', 'spk-ja-n5-15-katta', 9, 'prompt', 'How would you say "The school was small"?', '学校は小さかったです。', 'がっこう わ ちいさかった です。', NULL),
  ('spk-ja-n5-15-katta-s10', 'spk-ja-n5-15-katta', 10, 'prompt', 'How would you say "It was expensive"?', '高かったです。', 'たかかった です。', NULL),
  ('spk-ja-n5-15-katta-s11', 'spk-ja-n5-15-katta', 11, 'prompt', 'How would you say "It was not expensive"?', '高くなかったです。', 'たかくなかった です。', NULL),
  ('spk-ja-n5-15-katta-s12', 'spk-ja-n5-15-katta', 12, 'prompt', 'How would you say "Was the restaurant expensive?"', 'レストランは高かったですか。', 'レストラン わ たかかった です か。', NULL),
  ('spk-ja-n5-15-katta-s13', 'spk-ja-n5-15-katta', 13, 'explain', 'The {しずか} kind works like a noun. {です} becomes {でした}. And "was not" is {じゃありませんでした}.', NULL, NULL, NULL),
  ('spk-ja-n5-15-katta-s14', 'spk-ja-n5-15-katta', 14, 'prompt', 'How would you say "The restaurant was quiet"?', 'レストランはしずかでした。', 'レストラン わ しずか でした。', NULL),
  ('spk-ja-n5-15-katta-s15', 'spk-ja-n5-15-katta', 15, 'prompt', 'How would you say "The restaurant was not quiet"?', 'レストランはしずかじゃありませんでした。', 'レストラン わ しずか じゃ ありません でした。', NULL),
  ('spk-ja-n5-15-katta-s16', 'spk-ja-n5-15-katta', 16, 'prompt', 'How would you say "Japan was pretty"?', '日本はきれいでした。', 'にほん わ きれい でした。', NULL),
  ('spk-ja-n5-15-katta-s17', 'spk-ja-n5-15-katta', 17, 'explain', '"Good" is {いい}. It changes shape in the past. It becomes {よかったです}.', NULL, NULL, NULL),
  ('spk-ja-n5-15-katta-s18', 'spk-ja-n5-15-katta', 18, 'prompt', 'How would you say "The restaurant was good"?', 'レストランはよかったです。', 'レストラン わ よかった です。', NULL),
  ('spk-ja-n5-15-katta-s19', 'spk-ja-n5-15-katta', 19, 'prompt', 'How would you say "I went to Japan yesterday. It was pretty."?', 'きのう、日本に行きました。きれいでした。', 'きのう、にほん に いきました。きれい でした。', NULL),
  ('spk-ja-n5-15-katta-s20', 'spk-ja-n5-15-katta', 20, 'prompt', 'How would you say "I ate sushi yesterday. It was delicious."?', 'きのう、すしを食べました。おいしかったです。', 'きのう、すし お たべました。おいしかった です。', NULL),
  ('spk-ja-n5-15-katta-s21', 'spk-ja-n5-15-katta', 21, 'prompt', 'How would you say "It was delicious, so I ate it every day"?', 'おいしかったですから、毎日、食べました。', 'おいしかった です から、まいにち、たべました。', NULL),
  ('spk-ja-n5-15-katta-s22', 'spk-ja-n5-15-katta', 22, 'prompt', 'How would you say "It was expensive, so I didn''t eat"?', '高かったですから、食べませんでした。', 'たかかった です から、たべませんでした。', NULL),
  ('spk-ja-n5-15-katta-s23', 'spk-ja-n5-15-katta', 23, 'prompt', 'How would you say "The restaurant was quiet, so I read a book there"?', 'レストランはしずかでしたから、レストランで本を読みました。', 'レストラン わ しずか でした から、レストラン で ほん お よみました。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-15-katta')
ON CONFLICT (session_id, index) DO NOTHING;

