-- N5 · 16 · What time? What day?
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-16-time', 'lang-ja', ll.id, 'n5-16-time', 16, '何時ですか', 'What time? What day?', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-16-time-s0', 'spk-ja-n5-16-time', 0, 'explain', 'Time. "O''clock" is {じ}. Seven is {なな} or {しち}, and with o''clock it is {しち}. So "seven o''clock" is {しちじ}. Add {です}.', NULL, NULL, NULL),
  ('spk-ja-n5-16-time-s1', 'spk-ja-n5-16-time', 1, 'prompt', 'How would you say "It is seven o''clock"?', '七時です。', 'しちじ です。', NULL),
  ('spk-ja-n5-16-time-s2', 'spk-ja-n5-16-time', 2, 'explain', 'Eight o''clock is {はちじ}.', NULL, NULL, NULL),
  ('spk-ja-n5-16-time-s3', 'spk-ja-n5-16-time', 3, 'prompt', 'How would you say "It is eight o''clock"?', '八時です。', 'はちじ です。', NULL),
  ('spk-ja-n5-16-time-s4', 'spk-ja-n5-16-time', 4, 'explain', '"What time" is {なんじ}. The question word sits where the answer would sit.', NULL, NULL, NULL),
  ('spk-ja-n5-16-time-s5', 'spk-ja-n5-16-time', 5, 'prompt', 'How would you say "What time is it?"', '何時ですか。', 'なんじ です か。', NULL),
  ('spk-ja-n5-16-time-s6', 'spk-ja-n5-16-time', 6, 'prompt', 'How would you say "Is it eight o''clock?"', '八時ですか。', 'はちじ です か。', NULL),
  ('spk-ja-n5-16-time-s7', 'spk-ja-n5-16-time', 7, 'explain', 'Nine o''clock is {くじ}.', NULL, NULL, NULL),
  ('spk-ja-n5-16-time-s8', 'spk-ja-n5-16-time', 8, 'prompt', 'How would you say "It is nine o''clock now"?', '今、九時です。', 'いま、くじ です。', NULL),
  ('spk-ja-n5-16-time-s9', 'spk-ja-n5-16-time', 9, 'prompt', 'How would you say "What time is it now?"', '今、何時ですか。', 'いま、なんじ です か。', NULL),
  ('spk-ja-n5-16-time-s10', 'spk-ja-n5-16-time', 10, 'explain', '"Half" is {はん}. {しちじはん}, half past seven.', NULL, NULL, NULL),
  ('spk-ja-n5-16-time-s11', 'spk-ja-n5-16-time', 11, 'prompt', 'How would you say "It is half past seven"?', '七時半です。', 'しちじ はん です。', NULL),
  ('spk-ja-n5-16-time-s12', 'spk-ja-n5-16-time', 12, 'explain', 'For the time when you do something, add {に}. {しちじに}, "at seven".', NULL, NULL, NULL),
  ('spk-ja-n5-16-time-s13', 'spk-ja-n5-16-time', 13, 'prompt', 'How would you say "I eat a meal at seven"?', '七時にごはんを食べます。', 'しちじ に ごはん お たべます。', NULL),
  ('spk-ja-n5-16-time-s14', 'spk-ja-n5-16-time', 14, 'prompt', 'How would you say "I go to school at eight"?', '八時に学校に行きます。', 'はちじ に がっこう に いきます。', NULL),
  ('spk-ja-n5-16-time-s15', 'spk-ja-n5-16-time', 15, 'prompt', 'How would you say "What time do you eat a meal?"', '何時にごはんを食べますか。', 'なんじ に ごはん お たべます か。', NULL),
  ('spk-ja-n5-16-time-s16', 'spk-ja-n5-16-time', 16, 'prompt', 'How would you say "What time do you go to school?"', '何時に学校に行きますか。', 'なんじ に がっこう に いきます か。', NULL),
  ('spk-ja-n5-16-time-s17', 'spk-ja-n5-16-time', 17, 'prompt', 'How would you say "What time did you go home yesterday?"', 'きのう、何時にうちに帰りましたか。', 'きのう、なんじ に うち に かえりました か。', NULL),
  ('spk-ja-n5-16-time-s18', 'spk-ja-n5-16-time', 18, 'explain', '"Get up" is {おきます}. Six o''clock is {ろくじ}.', NULL, NULL, NULL),
  ('spk-ja-n5-16-time-s19', 'spk-ja-n5-16-time', 19, 'prompt', 'How would you say "I get up at six"?', '六時におきます。', 'ろくじ に おきます。', NULL),
  ('spk-ja-n5-16-time-s20', 'spk-ja-n5-16-time', 20, 'prompt', 'How would you say "What time do you get up?"', '何時におきますか。', 'なんじ に おきます か。', NULL),
  ('spk-ja-n5-16-time-s21', 'spk-ja-n5-16-time', 21, 'explain', '"Sleep" is {ねます}. Ten o''clock is {じゅうじ}.', NULL, NULL, NULL),
  ('spk-ja-n5-16-time-s22', 'spk-ja-n5-16-time', 22, 'prompt', 'How would you say "I sleep at ten"?', '十時にねます。', 'じゅうじ に ねます。', NULL),
  ('spk-ja-n5-16-time-s23', 'spk-ja-n5-16-time', 23, 'explain', 'Now days. Monday is {げつようび}. Every day of the week ends in {ようび}.', NULL, NULL, NULL),
  ('spk-ja-n5-16-time-s24', 'spk-ja-n5-16-time', 24, 'prompt', 'How would you say "Today is Monday"?', '今日は月曜日です。', 'きょう わ げつようび です。', NULL),
  ('spk-ja-n5-16-time-s25', 'spk-ja-n5-16-time', 25, 'explain', '"What day" is {なんようび}. The same {なん}, before the day ending.', NULL, NULL, NULL),
  ('spk-ja-n5-16-time-s26', 'spk-ja-n5-16-time', 26, 'prompt', 'How would you say "What day is it today?"', '今日は何曜日ですか。', 'きょう わ なんようび です か。', NULL),
  ('spk-ja-n5-16-time-s27', 'spk-ja-n5-16-time', 27, 'explain', 'Sunday is {にちようび}. Saturday is {どようび}.', NULL, NULL, NULL),
  ('spk-ja-n5-16-time-s28', 'spk-ja-n5-16-time', 28, 'prompt', 'How would you say "Tomorrow is Sunday"?', 'あしたは日曜日です。', 'あした わ にちようび です。', NULL),
  ('spk-ja-n5-16-time-s29', 'spk-ja-n5-16-time', 29, 'prompt', 'How would you say "Yesterday was Saturday"?', 'きのうは土曜日でした。', 'きのう わ どようび でした。', NULL),
  ('spk-ja-n5-16-time-s30', 'spk-ja-n5-16-time', 30, 'prompt', 'How would you say "I go to school on Monday"?', '月曜日に学校に行きます。', 'げつようび に がっこう に いきます。', NULL),
  ('spk-ja-n5-16-time-s31', 'spk-ja-n5-16-time', 31, 'prompt', 'How would you say "I don''t go to school on Sunday"?', '日曜日は学校に行きません。', 'にちようび わ がっこう に いきません。', NULL),
  ('spk-ja-n5-16-time-s32', 'spk-ja-n5-16-time', 32, 'prompt', 'How would you say "I read a book on Saturday"?', '土曜日に本を読みます。', 'どようび に ほん お よみます。', NULL),
  ('spk-ja-n5-16-time-s33', 'spk-ja-n5-16-time', 33, 'prompt', 'How would you say "I get up at seven on Sunday"?', '日曜日は七時におきます。', 'にちようび わ しちじ に おきます。', 'Sunday becomes the topic. The time keeps に.')
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-16-time')
ON CONFLICT (session_id, index) DO NOTHING;

