-- N5 · 17 · Comparing
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-17-hou-ga', 'lang-ja', ll.id, 'n5-17-hou-ga', 17, 'すしのほうがおいしい', 'Comparing', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-17-hou-ga-s0', 'spk-ja-n5-17-hou-ga', 0, 'explain', 'To compare, the little word {より} means "than". It comes after the thing you compare against. {それより}, "than that". Start with what you are describing. {これはそれよりおおきいです}, "this is bigger than that".', NULL, NULL, NULL),
  ('spk-ja-n5-17-hou-ga-s1', 'spk-ja-n5-17-hou-ga', 1, 'prompt', 'How would you say "This is bigger than that"?', 'これはそれより大きいです。', 'これ わ それ より おおきい です。', NULL),
  ('spk-ja-n5-17-hou-ga-s2', 'spk-ja-n5-17-hou-ga', 2, 'prompt', 'How would you say "That is smaller than this"?', 'それはこれより小さいです。', 'それ わ これ より ちいさい です。', NULL),
  ('spk-ja-n5-17-hou-ga-s3', 'spk-ja-n5-17-hou-ga', 3, 'prompt', 'How would you say "Sushi is more delicious than rice"?', 'すしはごはんよりおいしいです。', 'すし わ ごはん より おいしい です。', NULL),
  ('spk-ja-n5-17-hou-ga-s4', 'spk-ja-n5-17-hou-ga', 4, 'prompt', 'How would you say "Tea is more expensive than water"?', 'おちゃは水より高いです。', 'おちゃ わ みず より たかい です。', NULL),
  ('spk-ja-n5-17-hou-ga-s5', 'spk-ja-n5-17-hou-ga', 5, 'prompt', 'How would you say "The school is quieter than the restaurant"?', '学校はレストランよりしずかです。', 'がっこう わ レストラン より しずか です。', NULL),
  ('spk-ja-n5-17-hou-ga-s6', 'spk-ja-n5-17-hou-ga', 6, 'prompt', 'How would you say "The restaurant is prettier than the school"?', 'レストランは学校よりきれいです。', 'レストラン わ がっこう より きれい です。', NULL),
  ('spk-ja-n5-17-hou-ga-s7', 'spk-ja-n5-17-hou-ga', 7, 'prompt', 'How would you say "Is the sushi more delicious than the rice?"', 'すしはごはんよりおいしいですか。', 'すし わ ごはん より おいしい です か。', NULL),
  ('spk-ja-n5-17-hou-ga-s8', 'spk-ja-n5-17-hou-ga', 8, 'prompt', 'How would you say "Japan is prettier than this school"?', '日本はこの学校よりきれいです。', 'にほん わ この がっこう より きれい です。', NULL),
  ('spk-ja-n5-17-hou-ga-s9', 'spk-ja-n5-17-hou-ga', 9, 'prompt', 'How would you say "The sushi was more delicious than the rice"?', 'すしはごはんよりおいしかったです。', 'すし わ ごはん より おいしかった です。', NULL),
  ('spk-ja-n5-17-hou-ga-s10', 'spk-ja-n5-17-hou-ga', 10, 'explain', 'To ask "which of the two", use {どちら}. First name both things with {と}, "and". Then {どちらのほうが}, "which one is more". {これとそれと、どちらのほうが}.', NULL, NULL, NULL),
  ('spk-ja-n5-17-hou-ga-s11', 'spk-ja-n5-17-hou-ga', 11, 'prompt', 'How would you say "Which is bigger, this or that?"', 'これとそれと、どちらのほうが大きいですか。', 'これ と それ と、どちら の ほう が おおきい です か。', NULL),
  ('spk-ja-n5-17-hou-ga-s12', 'spk-ja-n5-17-hou-ga', 12, 'explain', 'To answer, name the winner and add {のほうが}. {これのほうが}.', NULL, NULL, NULL),
  ('spk-ja-n5-17-hou-ga-s13', 'spk-ja-n5-17-hou-ga', 13, 'prompt', 'How would you say "This one is bigger"?', 'これのほうが大きいです。', 'これ の ほう が おおきい です。', NULL),
  ('spk-ja-n5-17-hou-ga-s14', 'spk-ja-n5-17-hou-ga', 14, 'prompt', 'How would you say "Which is more delicious, sushi or rice?"', 'すしとごはんと、どちらのほうがおいしいですか。', 'すし と ごはん と、どちら の ほう が おいしい です か。', NULL),
  ('spk-ja-n5-17-hou-ga-s15', 'spk-ja-n5-17-hou-ga', 15, 'prompt', 'How would you say "Sushi is more delicious"?', 'すしのほうがおいしいです。', 'すし の ほう が おいしい です。', NULL),
  ('spk-ja-n5-17-hou-ga-s16', 'spk-ja-n5-17-hou-ga', 16, 'prompt', 'How would you say "Which is more expensive, tea or water?"', 'おちゃと水と、どちらのほうが高いですか。', 'おちゃ と みず と、どちら の ほう が たかい です か。', NULL),
  ('spk-ja-n5-17-hou-ga-s17', 'spk-ja-n5-17-hou-ga', 17, 'explain', '"Like" is {すき}. It is the {しずか} kind, and the thing you like takes {が}. {すしがすきです}.', NULL, NULL, NULL),
  ('spk-ja-n5-17-hou-ga-s18', 'spk-ja-n5-17-hou-ga', 18, 'prompt', 'How would you say "I like sushi"?', 'すしがすきです。', 'すし が すき です。', NULL),
  ('spk-ja-n5-17-hou-ga-s19', 'spk-ja-n5-17-hou-ga', 19, 'explain', 'With {すき}, the thing you like keeps {が}. So put the {より} part first. {ごはんより}, then {すしがすきです}.', NULL, NULL, NULL),
  ('spk-ja-n5-17-hou-ga-s20', 'spk-ja-n5-17-hou-ga', 20, 'prompt', 'How would you say "I like sushi more than rice"?', 'ごはんよりすしがすきです。', 'ごはん より すし が すき です。', NULL),
  ('spk-ja-n5-17-hou-ga-s21', 'spk-ja-n5-17-hou-ga', 21, 'prompt', 'How would you say "Which do you like more, sushi or rice?"', 'すしとごはんと、どちらのほうがすきですか。', 'すし と ごはん と、どちら の ほう が すき です か。', NULL),
  ('spk-ja-n5-17-hou-ga-s22', 'spk-ja-n5-17-hou-ga', 22, 'prompt', 'How would you say "I like tea more"?', 'おちゃのほうがすきです。', 'おちゃ の ほう が すき です。', NULL),
  ('spk-ja-n5-17-hou-ga-s23', 'spk-ja-n5-17-hou-ga', 23, 'prompt', 'How would you say "Tea is more delicious than water, so I drink tea every day"?', 'おちゃは水よりおいしいですから、毎日、おちゃを飲みます。', 'おちゃ わ みず より おいしい です から、まいにち、おちゃ お のみます。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-17-hou-ga')
ON CONFLICT (session_id, index) DO NOTHING;

