SELECT 'crq-spk-ja-n5-17-hou-ga', 'lang-ja', 'speak_sessions', 'spk-ja-n5-17-hou-ga', 'create', '{"code":"n5-17-hou-ga","level":"N5","number":17}'::jsonb, 'ai', 1017, 'pending'
