ON CONFLICT DO NOTHING;

-- N5 · 18 · Please don't
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-18-naide', 'lang-ja', ll.id, 'n5-18-naide', 18, '食べないでください', 'Please don''t', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-18-naide-s0', 'spk-ja-n5-18-naide', 0, 'explain', 'To ask someone not to do something, you need the "not" form of the verb. For {たべます}, drop {ます} and add {ない}. {たべない}. Then add {でください}. {たべないでください}. "Please don''t eat."', NULL, NULL, NULL),
  ('spk-ja-n5-18-naide-s1', 'spk-ja-n5-18-naide', 1, 'prompt', 'How would you say "Please don''t eat"?', '食べないでください。', 'たべない で ください。', NULL),
  ('spk-ja-n5-18-naide-s2', 'spk-ja-n5-18-naide', 2, 'prompt', 'How would you say "Please don''t eat sushi"?', 'すしを食べないでください。', 'すし お たべない で ください。', NULL),
  ('spk-ja-n5-18-naide-s3', 'spk-ja-n5-18-naide', 3, 'explain', '{みます} works like {たべます}. Drop {ます}, add {ない}. {みない}.', NULL, NULL, NULL),
  ('spk-ja-n5-18-naide-s4', 'spk-ja-n5-18-naide', 4, 'prompt', 'How would you say "Please don''t look at this"?', 'これを見ないでください。', 'これ お みない で ください。', NULL),
  ('spk-ja-n5-18-naide-s5', 'spk-ja-n5-18-naide', 5, 'explain', 'For {よみます}, the {み} becomes {ま}. {よまない}. Then {よまないでください}.', NULL, NULL, NULL),
  ('spk-ja-n5-18-naide-s6', 'spk-ja-n5-18-naide', 6, 'prompt', 'How would you say "Please don''t read this"?', 'これを読まないでください。', 'これ お よまない で ください。', NULL),
  ('spk-ja-n5-18-naide-s7', 'spk-ja-n5-18-naide', 7, 'explain', '{のみます} does the same. {のまない}.', NULL, NULL, NULL),
  ('spk-ja-n5-18-naide-s8', 'spk-ja-n5-18-naide', 8, 'prompt', 'How would you say "Please don''t drink water"?', '水を飲まないでください。', 'みず お のまない で ください。', NULL),
  ('spk-ja-n5-18-naide-s9', 'spk-ja-n5-18-naide', 9, 'prompt', 'How would you say "Please don''t drink tea"?', 'おちゃを飲まないでください。', 'おちゃ お のまない で ください。', NULL),
  ('spk-ja-n5-18-naide-s10', 'spk-ja-n5-18-naide', 10, 'explain', '{いきます} becomes {いかない}. {かえります} becomes {かえらない}.', NULL, NULL, NULL),
  ('spk-ja-n5-18-naide-s11', 'spk-ja-n5-18-naide', 11, 'prompt', 'How would you say "Please don''t go"?', '行かないでください。', 'いかない で ください。', NULL),
  ('spk-ja-n5-18-naide-s12', 'spk-ja-n5-18-naide', 12, 'prompt', 'How would you say "Please don''t go to the restaurant"?', 'レストランに行かないでください。', 'レストラン に いかない で ください。', NULL),
  ('spk-ja-n5-18-naide-s13', 'spk-ja-n5-18-naide', 13, 'prompt', 'How would you say "Please don''t go home"?', 'うちに帰らないでください。', 'うち に かえらない で ください。', NULL),
  ('spk-ja-n5-18-naide-s14', 'spk-ja-n5-18-naide', 14, 'explain', '{かきます} becomes {かかない}.', NULL, NULL, NULL),
  ('spk-ja-n5-18-naide-s15', 'spk-ja-n5-18-naide', 15, 'prompt', 'How would you say "Please don''t write here"?', 'ここに書かないでください。', 'ここ に かかない で ください。', NULL),
  ('spk-ja-n5-18-naide-s16', 'spk-ja-n5-18-naide', 16, 'explain', '{きます}, to come, is special. It becomes {こない}.', NULL, NULL, NULL),
  ('spk-ja-n5-18-naide-s17', 'spk-ja-n5-18-naide', 17, 'prompt', 'How would you say "Please don''t come"?', '来ないでください。', 'こない で ください。', NULL),
  ('spk-ja-n5-18-naide-s18', 'spk-ja-n5-18-naide', 18, 'prompt', 'How would you say "Please don''t come to my home"?', 'わたしのうちに来ないでください。', 'わたし の うち に こない で ください。', NULL),
  ('spk-ja-n5-18-naide-s19', 'spk-ja-n5-18-naide', 19, 'prompt', 'How would you say "Please don''t eat here"?', 'ここで食べないでください。', 'ここ で たべない で ください。', NULL),
  ('spk-ja-n5-18-naide-s20', 'spk-ja-n5-18-naide', 20, 'prompt', 'How would you say "Please don''t watch TV here"?', 'ここでテレビを見ないでください。', 'ここ で テレビ お みない で ください。', NULL),
  ('spk-ja-n5-18-naide-s21', 'spk-ja-n5-18-naide', 21, 'explain', '{ききます} becomes {きかない}.', NULL, NULL, NULL),
  ('spk-ja-n5-18-naide-s22', 'spk-ja-n5-18-naide', 22, 'prompt', 'How would you say "Please don''t listen to this"?', 'これを聞かないでください。', 'これ お きかない で ください。', NULL),
  ('spk-ja-n5-18-naide-s23', 'spk-ja-n5-18-naide', 23, 'prompt', 'How would you say "It is expensive, so please don''t eat"?', '高いですから、食べないでください。', 'たかい です から、たべない で ください。', NULL),
  ('spk-ja-n5-18-naide-s24', 'spk-ja-n5-18-naide', 24, 'prompt', 'How would you say "It is quiet here, so please don''t watch TV"?', 'ここはしずかですから、テレビを見ないでください。', 'ここ わ しずか です から、テレビ お みない で ください。', NULL),
  ('spk-ja-n5-18-naide-s25', 'spk-ja-n5-18-naide', 25, 'prompt', 'How would you say "I am reading a book now, so please don''t watch TV"?', '今、本を読んでいますから、テレビを見ないでください。', 'いま、ほん お よんで います から、テレビ お みない で ください。', NULL),
  ('spk-ja-n5-18-naide-s26', 'spk-ja-n5-18-naide', 26, 'prompt', 'How would you say "After you eat, please don''t drink tea"?', '食べてから、おちゃを飲まないでください。', 'たべて から、おちゃ お のまない で ください。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
WHERE EXISTS (SELECT 1 FROM speak_sessions WHERE id = 'spk-ja-n5-18-naide')
ON CONFLICT (session_id, index) DO NOTHING;

