-- N5 · 19 · I have done it before
INSERT INTO speak_sessions (id, language_id, level_id, code, number, title, title_en, published)
SELECT 'spk-ja-n5-19-takoto', 'lang-ja', ll.id, 'n5-19-takoto', 19, '行ったことがあります', 'I have done it before', false
FROM language_levels ll
WHERE ll.language_id = 'lang-ja' AND ll.code = 'N5'
ON CONFLICT (language_id, code) DO NOTHING;

INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-19-takoto-s0', 'spk-ja-n5-19-takoto', 0, 'explain', 'To say you have done something before, first make the past plain form. Take the {て} form and change {て} to {た}. {たべて} becomes {たべた}. Then add {ことがあります}, "I have the experience of". {たべたことがあります}.', NULL, NULL, NULL),
  ('spk-ja-n5-19-takoto-s1', 'spk-ja-n5-19-takoto', 1, 'prompt', 'How would you say "I have eaten sushi"?', 'すしを食べたことがあります。', 'すし お たべた こと が あります。', NULL),
  ('spk-ja-n5-19-takoto-s2', 'spk-ja-n5-19-takoto', 2, 'explain', '{いって} becomes {いった}.', NULL, NULL, NULL),
  ('spk-ja-n5-19-takoto-s3', 'spk-ja-n5-19-takoto', 3, 'prompt', 'How would you say "I have been to Japan"?', '日本に行ったことがあります。', 'にほん に いった こと が あります。', NULL),
  ('spk-ja-n5-19-takoto-s4', 'spk-ja-n5-19-takoto', 4, 'prompt', 'How would you say "Have you been to Japan?"', '日本に行ったことがありますか。', 'にほん に いった こと が あります か。', NULL),
  ('spk-ja-n5-19-takoto-s5', 'spk-ja-n5-19-takoto', 5, 'prompt', 'How would you say "Yes, I have"?', 'はい、あります。', 'はい、あります。', NULL),
  ('spk-ja-n5-19-takoto-s6', 'spk-ja-n5-19-takoto', 6, 'prompt', 'How would you say "No, I haven''t"?', 'いいえ、ありません。', 'いいえ、ありません。', NULL),
  ('spk-ja-n5-19-takoto-s7', 'spk-ja-n5-19-takoto', 7, 'explain', '{のんで} becomes {のんだ}, with {だ} this time. "Japanese", before a thing, can be {にほんの}, "Japan''s".', NULL, NULL, NULL),
  ('spk-ja-n5-19-takoto-s8', 'spk-ja-n5-19-takoto', 8, 'prompt', 'How would you say "I have drunk Japanese tea"?', '日本のおちゃを飲んだことがあります。', 'にほん の おちゃ お のんだ こと が あります。', NULL),
  ('spk-ja-n5-19-takoto-s9', 'spk-ja-n5-19-takoto', 9, 'prompt', 'How would you say "I have read this book"?', 'この本を読んだことがあります。', 'この ほん お よんだ こと が あります。', NULL),
  ('spk-ja-n5-19-takoto-s10', 'spk-ja-n5-19-takoto', 10, 'prompt', 'How would you say "Have you read this book?"', 'この本を読んだことがありますか。', 'この ほん お よんだ こと が あります か。', NULL),
  ('spk-ja-n5-19-takoto-s11', 'spk-ja-n5-19-takoto', 11, 'prompt', 'How would you say "I have seen this"?', 'これを見たことがあります。', 'これ お みた こと が あります。', NULL),
  ('spk-ja-n5-19-takoto-s12', 'spk-ja-n5-19-takoto', 12, 'prompt', 'How would you say "I have watched Japanese TV"?', '日本のテレビを見たことがあります。', 'にほん の テレビ お みた こと が あります。', NULL),
  ('spk-ja-n5-19-takoto-s13', 'spk-ja-n5-19-takoto', 13, 'explain', 'To say you never have, change the end to {ことがありません}.', NULL, NULL, NULL),
  ('spk-ja-n5-19-takoto-s14', 'spk-ja-n5-19-takoto', 14, 'prompt', 'How would you say "I have never eaten sushi"?', 'すしを食べたことがありません。', 'すし お たべた こと が ありません。', NULL),
  ('spk-ja-n5-19-takoto-s15', 'spk-ja-n5-19-takoto', 15, 'prompt', 'How would you say "I have never been to Japan"?', '日本に行ったことがありません。', 'にほん に いった こと が ありません。', NULL),
  ('spk-ja-n5-19-takoto-s16', 'spk-ja-n5-19-takoto', 16, 'prompt', 'How would you say "Have you ever eaten at a restaurant in Japan?"', '日本のレストランで食べたことがありますか。', 'にほん の レストラン で たべた こと が あります か。', NULL),
  ('spk-ja-n5-19-takoto-s17', 'spk-ja-n5-19-takoto', 17, 'prompt', 'How would you say "No, I haven''t"?', 'いいえ、ありません。', 'いいえ、ありません。', NULL),
  ('spk-ja-n5-19-takoto-s18', 'spk-ja-n5-19-takoto', 18, 'explain', '{きて} becomes {きた}.', NULL, NULL, NULL),
  ('spk-ja-n5-19-takoto-s19', 'spk-ja-n5-19-takoto', 19, 'prompt', 'How would you say "I have come to this school before"?', 'この学校に来たことがあります。', 'この がっこう に きた こと が あります。', NULL),
  ('spk-ja-n5-19-takoto-s20', 'spk-ja-n5-19-takoto', 20, 'prompt', 'How would you say "I have been to this restaurant"?', 'このレストランに行ったことがあります。', 'この レストラン に いった こと が あります。', NULL),
  ('spk-ja-n5-19-takoto-s21', 'spk-ja-n5-19-takoto', 21, 'prompt', 'How would you say "Have you been to this restaurant?"', 'このレストランに行ったことがありますか。', 'この レストラン に いった こと が あります か。', NULL),
  ('spk-ja-n5-19-takoto-s22', 'spk-ja-n5-19-takoto', 22, 'prompt', 'How would you say "Yes, I have. It was delicious."?', 'はい、あります。おいしかったです。', 'はい、あります。おいしかった です。', NULL),
  ('spk-ja-n5-19-takoto-s23', 'spk-ja-n5-19-takoto', 23, 'explain', '"Once" is {いちど}.', NULL, NULL, NULL),
  ('spk-ja-n5-19-takoto-s24', 'spk-ja-n5-19-takoto', 24, 'prompt', 'How would you say "I have been to Japan once"?', '日本にいちど行ったことがあります。', 'にほん に いちど いった こと が あります。', NULL),
  ('spk-ja-n5-19-takoto-s25', 'spk-ja-n5-19-takoto', 25, 'prompt', 'How would you say "I have been to Japan. It was pretty."?', '日本に行ったことがあります。きれいでした。', 'にほん に いった こと が あります。きれい でした。', NULL)
