INSERT INTO speak_steps (id, session_id, index, kind, en, text, reading_kana, note)
SELECT v.* FROM (VALUES
  ('spk-ja-n5-20-tari-s0', 'spk-ja-n5-20-tari', 0, 'explain', 'To list things you do, as examples, take the {た} form and add {り}. {たべたり}. Do it twice, then finish with {します}, which is "do". {たべたり、のんだりします}. "I do things like eating and drinking."', NULL, NULL, NULL),
  ('spk-ja-n5-20-tari-s1', 'spk-ja-n5-20-tari', 1, 'prompt', 'How would you say "I eat and drink, among other things"?', '食べたり、飲んだりします。', 'たべたり、のんだり します。', NULL),
  ('spk-ja-n5-20-tari-s2', 'spk-ja-n5-20-tari', 2, 'prompt', 'How would you say "I watch TV and read books, among other things"?', 'テレビを見たり、本を読んだりします。', 'テレビ お みたり、ほん お よんだり します。', NULL),
  ('spk-ja-n5-20-tari-s3', 'spk-ja-n5-20-tari', 3, 'prompt', 'How would you say "On Sunday I watch TV and read books, among other things"?', '日曜日に、テレビを見たり、本を読んだりします。', 'にちようび に、テレビ お みたり、ほん お よんだり します。', NULL),
  ('spk-ja-n5-20-tari-s4', 'spk-ja-n5-20-tari', 4, 'prompt', 'How would you say "At school I read and write, among other things"?', '学校で、読んだり、書いたりします。', 'がっこう で、よんだり、かいたり します。', NULL),
  ('spk-ja-n5-20-tari-s5', 'spk-ja-n5-20-tari', 5, 'explain', 'In the past, {します} becomes {しました}.', NULL, NULL, NULL),
  ('spk-ja-n5-20-tari-s6', 'spk-ja-n5-20-tari', 6, 'prompt', 'How would you say "Yesterday I watched TV and read books, among other things"?', 'きのう、テレビを見たり、本を読んだりしました。', 'きのう、テレビ お みたり、ほん お よんだり しました。', NULL),
  ('spk-ja-n5-20-tari-s7', 'spk-ja-n5-20-tari', 7, 'prompt', 'How would you say "On Saturday I go to the restaurant and read books at home, among other things"?', '土曜日は、レストランに行ったり、うちで本を読んだりします。', 'どようび わ、レストラン に いったり、うち で ほん お よんだり します。', NULL),
  ('spk-ja-n5-20-tari-s8', 'spk-ja-n5-20-tari', 8, 'explain', '"What" is {なに}. It is the thing you do, so it takes {を}. {なにをしますか}, "what do you do?"', NULL, NULL, NULL),
  ('spk-ja-n5-20-tari-s9', 'spk-ja-n5-20-tari', 9, 'prompt', 'How would you say "What do you do on Sunday?"', '日曜日は何をしますか。', 'にちようび わ なに お します か。', NULL),
  ('spk-ja-n5-20-tari-s10', 'spk-ja-n5-20-tari', 10, 'prompt', 'How would you say "I watch TV and eat sushi, among other things"?', 'テレビを見たり、すしを食べたりします。', 'テレビ お みたり、すし お たべたり します。', NULL),
  ('spk-ja-n5-20-tari-s11', 'spk-ja-n5-20-tari', 11, 'prompt', 'How would you say "What did you do yesterday?"', 'きのう、何をしましたか。', 'きのう、なに お しました か。', NULL),
  ('spk-ja-n5-20-tari-s12', 'spk-ja-n5-20-tari', 12, 'explain', 'Now everything comes together, from all twenty sessions. It is all yours to use.', NULL, NULL, NULL),
  ('spk-ja-n5-20-tari-s13', 'spk-ja-n5-20-tari', 13, 'prompt', 'How would you say "I have a friend in Japan, so I want to go tomorrow"?', '日本に友だちがいますから、あした行きたいです。', 'にほん に ともだち が います から、あした いきたい です。', NULL),
  ('spk-ja-n5-20-tari-s14', 'spk-ja-n5-20-tari', 14, 'prompt', 'How would you say "Have you been to Japan? Yes, I have. It was pretty."?', '日本に行ったことがありますか。はい、あります。きれいでした。', 'にほん に いった こと が あります か。はい、あります。きれい でした。', NULL),
  ('spk-ja-n5-20-tari-s15', 'spk-ja-n5-20-tari', 15, 'prompt', 'How would you say "Which do you like more, sushi or rice?"', 'すしとごはんと、どちらのほうがすきですか。', 'すし と ごはん と、どちら の ほう が すき です か。', NULL),
  ('spk-ja-n5-20-tari-s16', 'spk-ja-n5-20-tari', 16, 'prompt', 'How would you say "It is quiet, so may I read a book here?"', 'しずかですから、ここで本を読んでもいいですか。', 'しずか です から、ここ で ほん お よんでも いい です か。', NULL),
  ('spk-ja-n5-20-tari-s17', 'spk-ja-n5-20-tari', 17, 'prompt', 'How would you say "After I eat at seven, I watch TV and read books, among other things"?', '七時に食べてから、テレビを見たり、本を読んだりします。', 'しちじ に たべて から、テレビ お みたり、ほん お よんだり します。', NULL),
  ('spk-ja-n5-20-tari-s18', 'spk-ja-n5-20-tari', 18, 'prompt', 'How would you say "Won''t you come to my home on Sunday? Let''s eat sushi and watch TV, among other things."?', '日曜日、わたしのうちに来ませんか。すしを食べたり、テレビを見たりしましょう。', 'にちようび、わたし の うち に きません か。すし お たべたり、テレビ お みたり しましょう。', NULL),
  ('spk-ja-n5-20-tari-s19', 'spk-ja-n5-20-tari', 19, 'prompt', 'How would you say "The restaurant in Japan was not expensive, so I went every day"?', '日本のレストランは高くなかったですから、毎日、行きました。', 'にほん の レストラン わ たかくなかった です から、まいにち、いきました。', NULL),
  ('spk-ja-n5-20-tari-s20', 'spk-ja-n5-20-tari', 20, 'prompt', 'How would you say "I go to school at eight every day, so I get up at seven"?', '毎日、八時に学校に行きますから、七時におきます。', 'まいにち、はちじ に がっこう に いきます から、しちじ に おきます。', NULL),
  ('spk-ja-n5-20-tari-s21', 'spk-ja-n5-20-tari', 21, 'prompt', 'How would you say "Please don''t eat here. Let''s go to the restaurant."?', 'ここで食べないでください。レストランに行きましょう。', 'ここ で たべない で ください。レストラン に いきましょう。', NULL),
  ('spk-ja-n5-20-tari-s22', 'spk-ja-n5-20-tari', 22, 'prompt', 'How would you say "Yesterday, at a restaurant in Japan, I ate sushi and drank tea, among other things. It was delicious."?', 'きのう、日本のレストランで、すしを食べたり、おちゃを飲んだりしました。おいしかったです。', 'きのう、にほん の レストラン で、すし お たべたり、おちゃ お のんだり しました。おいしかった です。', NULL)
) AS v(id, session_id, index, kind, en, text, reading_kana, note)
